<?php require_once __DIR__.'/../includes/functions.php';if($_SERVER['REQUEST_METHOD']!=='POST')go('/laporwarga/register.php');check_csrf();$name=trim($_POST['nama_lengkap']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['no_hp']??'');$address=trim($_POST['alamat']??'');$password=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){flash('error','Isi nama, email valid, dan kata sandi minimal 8 karakter.');go('/laporwarga/register.php');}try{$s=db()->prepare("INSERT INTO users(nama_lengkap,email,password,no_hp,alamat,role) VALUES(?,?,?,?,?,'masyarakat')");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone,$address]);log_activity('registrasi','Akun masyarakat dibuat');flash('success','Registrasi berhasil. Silakan masuk.');go('/laporwarga/login.php');}catch(Throwable $e){flash('error','Email sudah digunakan atau akun gagal dibuat.');go('/laporwarga/register.php');}